add_action( 'rest_api_init', function () {
    register_rest_field( 'post', 'focus_keyword', [
        'get_callback' => function ( $post_arr ) {
            $post_id = isset( $post_arr['id'] ) ? (int) $post_arr['id'] : 0;
            return $post_id ? get_post_meta( $post_id, '_yoast_wpseo_focuskw', true ) : '';
        },
        'update_callback' => function ( $value, $post_obj ) {
            $post_id = is_object( $post_obj ) && isset( $post_obj->ID ) ? (int) $post_obj->ID : 0;
            if ( ! $post_id ) return new WP_Error( 'rest_invalid_post', 'Post no válido', [ 'status' => 400 ] );
            if ( ! current_user_can( 'edit_post', $post_id ) ) return new WP_Error( 'rest_forbidden', 'Sin permisos', [ 'status' => 403 ] );
            if ( ! is_string( $value ) ) return new WP_Error( 'rest_invalid_param', 'La frase clave debe ser texto', [ 'status' => 400 ] );
            $focus_keyword = sanitize_text_field( $value );
            update_post_meta( $post_id, '_yoast_wpseo_focuskw', $focus_keyword );
            update_post_meta( $post_id, '_yoast_wpseo_focuskw_text_input', $focus_keyword );
            return true;
        },
        'schema' => [ 'type' => 'string', 'context' => [ 'view', 'edit' ] ],
    ] );
} );
